// Package transport builds the TLS credentials used to secure every gRPC
// channel in the mixnet (client<->mix and mix<->mix). Certificates are
// self-signed under a single local CA generated by scripts/gen_certs.sh.
//
// We use server-authenticated TLS: each mix presents a certificate signed by
// the shared CA, and the dialing side (a client or another mix) verifies that
// certificate against the CA and checks the server name. This is what TLS
// contributes to the system — confidentiality and integrity of each hop's
// transport plus authentication of the mix being talked to. It deliberately
// does NOT provide the sender/receiver unlinkability; that comes from the
// layered onion encryption and round batching (see the report).
package transport

import (
	"crypto/tls"
	"crypto/x509"
	"fmt"
	"os"

	"google.golang.org/grpc/credentials"
)

// ServerCredentials loads a mix server's certificate and private key and
// returns gRPC transport credentials presenting that certificate to dialers.
func ServerCredentials(certFile, keyFile string) (credentials.TransportCredentials, error) {
	cert, err := tls.LoadX509KeyPair(certFile, keyFile)
	if err != nil {
		return nil, fmt.Errorf("load server keypair (%s,%s): %w", certFile, keyFile, err)
	}
	cfg := &tls.Config{
		Certificates: []tls.Certificate{cert},
		MinVersion:   tls.VersionTLS12,
	}
	return credentials.NewTLS(cfg), nil
}

// ClientCredentials loads the CA certificate and returns gRPC transport
// credentials that verify a server's certificate against that CA. serverName
// must match a SAN in the target server's certificate (e.g. "server1" inside
// the Docker network, or "localhost" for local testing).
func ClientCredentials(caFile, serverName string) (credentials.TransportCredentials, error) {
	pem, err := os.ReadFile(caFile)
	if err != nil {
		return nil, fmt.Errorf("read CA cert %s: %w", caFile, err)
	}
	pool := x509.NewCertPool()
	if !pool.AppendCertsFromPEM(pem) {
		return nil, fmt.Errorf("CA cert %s contained no usable certificates", caFile)
	}
	cfg := &tls.Config{
		RootCAs:    pool,
		ServerName: serverName,
		MinVersion: tls.VersionTLS12,
	}
	return credentials.NewTLS(cfg), nil
}
